n = int(input("Digite o número apostado (dois dígitos): "))
l = int(input("Digite o número sorteado (dois dígitos): "))

if n == l:
    print("Ganhou R$ 100.000,00")
elif sorted(str(n)) == sorted(str(l)):
    print("Ganhou R$ 50.000,00")
elif str(n)[0] == str(l)[0] or str(n)[0] == str(l)[1] or str(n)[1] == str(l)[0] or str(n)[1] == str(l)[1]:
    print("Ganhou R$ 1.000,00")
else:
    print("Perdeu")
